import { fetchWithRetry } from "./fetchWithRetry";
import type { Charge, ChargeRequest, Refund } from "./types";

export interface PaymentsClientOptions {
  baseUrl: string;
  apiKey: string;
  /** Attempts after the first, for any failed request. */
  retries?: number;
  timeoutMs?: number;
}

export interface PaymentsClient {
  createCharge(request: ChargeRequest): Promise<Charge>;
  refund(chargeId: string): Promise<Refund>;
  getCharge(chargeId: string): Promise<Charge>;
}

export function createPaymentsClient({
  baseUrl,
  apiKey,
  retries = 3,
  timeoutMs = 10_000,
}: PaymentsClientOptions): PaymentsClient {
  const send = <T>(method: string, path: string, body?: unknown) =>
    fetchWithRetry<T>(`${baseUrl}${path}`, { method, body, apiKey, timeoutMs, retries });
  return {
    createCharge: (request) => send("POST", "/charges", request),
    refund: (chargeId) => send("POST", `/charges/${chargeId}/refunds`),
    getCharge: (chargeId) => send("GET", `/charges/${chargeId}`),
  };
}

