export interface RequestOptions {
  method: string;
  body?: unknown;
  apiKey: string;
  timeoutMs: number;
  retries: number;
}

/** Sends the request, and sends it again after any failure, up to `retries` more times. */
export async function fetchWithRetry<T>(url: string, options: RequestOptions): Promise<T> {
  for (let attempt = 0; ; attempt++) {
    try {
      const response = await fetch(url, {
        method: options.method,
        headers: { authorization: `Bearer ${options.apiKey}`, "content-type": "application/json" },
        body: options.body === undefined ? undefined : JSON.stringify(options.body),
        signal: AbortSignal.timeout(options.timeoutMs),
      });
      if (!response.ok) throw new Error(`payments ${response.status}`);
      return (await response.json()) as T;
    } catch (error) {
      if (attempt >= options.retries) throw error;
      await new Promise((resolve) => setTimeout(resolve, 200 * 2 ** attempt));
    }
  }
}

