import { provider } from "../payments";
import { InvalidRefundAmountError } from "./errors";

export async function createRefund(chargeId: string, amountCents?: number) {
  const charge = await loadCharge(chargeId);
  const amount = amountCents ?? charge.amountCents;
  if (amount <= 0 || amount > charge.amountCents) throw new InvalidRefundAmountError(amount);
  const refund = await provider.refund(charge.providerId, { amount });
