import type { NextFunction, Request, Response } from "express";
import { verifyCsrfToken } from "./csrf";
import { readSession } from "./session";

// Webhooks prove themselves with a signature, so they skip the session and CSRF checks.
const PUBLIC_PREFIXES = ["/health", "/webhooks/"];

const isPublic = (req: Request) => PUBLIC_PREFIXES.some((prefix) => req.path.startsWith(prefix));

export function requireSession(req: Request, res: Response, next: NextFunction) {
  if (isPublic(req)) return next();
  const session = readSession(req);
  if (!session) return res.status(401).end();
  res.locals.session = session;
  next();
}

export function requireCsrf(req: Request, res: Response, next: NextFunction) {
  if (req.method === "GET" || isPublic(req)) return next();
  if (!verifyCsrfToken(req)) return res.status(403).end();
  next();
}

