import { markInvoicePaid } from "../invoices/service";
import { notifyPaymentFailed } from "../notifications";
import type { BillingEvent } from "./types";

export async function onInvoicePaid(event: BillingEvent) {
  await markInvoicePaid(event.data.invoiceId);
}

export async function onPaymentFailed(event: BillingEvent) {
  await notifyPaymentFailed(event.data.customerId);
}

export const handlers = {
  "invoice.paid": onInvoicePaid,
