import type { Report } from "./types";

const HEADER = ["date", "customer", "amount"];

const escapeCell = (cell: string) => (/[",\n]/.test(cell) ? `"${cell.replaceAll('"', '""')}"` : cell);
const toRow = (row: Report["rows"][number]) => [row.date, row.customer, String(row.amountCents / 100)];

export function toCsv(report: Report): string {
  const rows = [HEADER, ...report.rows.map(toRow)];
  return rows.map((row) => row.map(escapeCell).join(",")).join("\n");
}

